<?php

namespace Tests\Support\OpenApi;

use Dedoc\Scramble\Contracts\Diagnostics\Diagnostic;
use Dedoc\Scramble\Generator;
use Dedoc\Scramble\GeneratorConfig;
use Dedoc\Scramble\Scramble;
use Illuminate\Routing\Route;

/**
 * The OpenAPI document of `/api/v1`, generated by Scramble itself (never over HTTP and never through the
 * `CacheableGenerator`, whose file cache dev and tests share) once per test process and kept: generating it takes
 * seconds. Its own API `contract` clones the app's configuration (filter, transformers, info) and documents only the
 * routes of `routes/api.php`, so routes a test registers under `api/v1/_t/` never land in it, whichever test asks first
 * (K3).
 */
final class Document
{
    public const API = 'contract';

    /** @var array<string, mixed>|null */
    private static ?array $document = null;

    /** @var array{seconds: float, bytes: int}|null */
    private static ?array $stats = null;

    /** @var list<string> */
    private static array $diagnostics = [];

    /**
     * @return array<string, mixed>
     */
    public static function get(): array
    {
        if (self::$document !== null) {
            return self::$document;
        }

        $config = self::config();

        memory_reset_peak_usage();
        $before = memory_get_usage();
        $started = hrtime(true);
        $result = app(Generator::class)->generate($config);
        // what generating needed on top of what the process held before (the suite's process grows with every test)
        self::$stats = ['seconds' => (hrtime(true) - $started) / 1e9, 'bytes' => memory_get_peak_usage() - $before];
        self::$diagnostics = $result->diagnostics()
            ->map(fn (Diagnostic $d) => $d->severity()->name.' '.$d->code().' '.($d->context()?->toArray()['label'] ?? '-').': '.$d->message())
            ->values()->all();

        return self::$document = $result->spec($config->openApiVersion());
    }

    /**
     * How long the generation took and how much memory it needed at its peak (K19).
     *
     * @return array{seconds: float, bytes: int}
     */
    public static function stats(): array
    {
        self::get();

        return self::$stats ?? ['seconds' => 0.0, 'bytes' => 0];
    }

    /**
     * What Scramble reported while analysing (`<severity> <code> <where>: <message>`); with `throwOnError` a failure throws.
     *
     * @return list<string>
     */
    public static function diagnostics(): array
    {
        self::get();

        return self::$diagnostics;
    }

    /**
     * The operation of a route, `$uri` as `Route::uri()` without `api/v1` (`/work-items/{item}` or `work-items/{item}`).
     *
     * @return array<string, mixed>|null
     */
    public static function operation(string $method, string $uri): ?array
    {
        $path = '/'.ltrim($uri, '/');

        return self::get()['paths'][$path][strtolower($method)] ?? null;
    }

    /**
     * Every operation of the document, keyed `"<METHOD> <path>"` (`GET /work-items/{item}`).
     *
     * @return array<string, array<string, mixed>>
     */
    public static function operations(): array
    {
        $operations = [];

        foreach (self::get()['paths'] ?? [] as $path => $item) {
            foreach ($item as $method => $operation) {
                if (in_array($method, ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'], true)) {
                    $operations[strtoupper($method).' '.$path] = $operation;
                }
            }
        }

        return $operations;
    }

    /**
     * Whether a route is part of the contract: under `api/v1/`, from a controller of the app, not a test route.
     */
    public static function documents(Route $route): bool
    {
        return str_starts_with($route->uri(), 'api/v1/')
            && ! str_contains($route->uri(), '_t/')
            && str_starts_with((string) $route->getControllerClass(), 'App\\Http\\Controllers\\');
    }

    private static function config(): GeneratorConfig
    {
        $apis = Scramble::getConfigurationsInstance()->all();

        if (! array_key_exists(self::API, $apis)) {
            $app = Scramble::getGeneratorConfig(Scramble::DEFAULT_API);
            Scramble::registerApi(self::API)->routes(fn (Route $route) => ($app->routes())($route) && self::documents($route));
        }

        return Scramble::getGeneratorConfig(self::API);
    }
}
